=Evaluate the candidate's [Master CV] against the provided [Job Description].

[Master CV]:
{{ $('InputCvJD').item.json.Master_cv }}

[Job Description]:
{{ $('InputCvJD').item.json.job_decription }}

Respond ONLY with the raw JSON object matching the schema in the system prompt.

parameters.jsCode:
// Parse output from LLM 1 (German Eligibility)
const rawText = $input.item.json.text || $input.item.json.response || $input.item.json.choices?.[0]?.message?.content;
const parsed = typeof rawText === 'string' ? JSON.parse(rawText.replace(/```json|```/g, '').trim()) : rawText;

const eligible = Boolean(parsed.eligible);
const jd = $('InputCvJD').item.json.job_decription || '';
const jd_in_german = /\b(wir suchen|deine aufgaben|dein profil|bewirb dich|anforderungen|aufgaben)\b/i.test(jd);

return {
  eligible,
  reason: eligible ? parsed.reason : (parsed.reason || 'Failed German requirement (B1+ required)'),
  jd_in_german
};

