// Parse output from LLM 2 (Full Scoring & Evaluation)
const j = $input.item.json;
const rawText = j.text || j.response || j.choices?.[0]?.message?.content || '';

// Read the JSON safely, even if the AI adds extra text around it
let parsed = null;
if (typeof rawText === 'object' && rawText !== null) {
  parsed = rawText;
} else {
  const s = String(rawText);
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try { parsed = JSON.parse(s.slice(start, end + 1)); } catch (e) { parsed = null; }
  }
}

const input = $('InputCvJD').item.json;
const step1 = $('OutputFormating').item.json;

// If the AI gave no usable answer: don't crash, report it instead
if (!parsed) {
  const errText = j.error ? ' Error: ' + String(j.error.message || j.error) : '';
  return {
    role_title: 'Unknown',
    company: 'Unknown',
    job_url: input.job_url,
    eligible: true,
    role_fit: 0, stage: 0, founder_proximity: 0, skills_tools: 0, location: 0,
    total: 0,
    score: 0,
    reason: 'AI scoring failed (empty or invalid reply) - please re-run this job.' + errText,
    jd_in_german: step1.jd_in_german,
    scoring_failed: true,
    passes: false
  };
}

const clamp = (v, max) => Math.max(0, Math.min(max, Number(v) || 0));

const role_fit = clamp(parsed.role_fit, 3);
const stage = clamp(parsed.stage, 2);
const founder_proximity = clamp(parsed.founder_proximity, 2);
const skills_tools = clamp(parsed.skills_tools, 2);
const location = clamp(parsed.location, 1);

const total = role_fit + stage + founder_proximity + skills_tools + location;
const score = Math.round((1 + 4 * (total / 10)) * 10) / 10;

return {
  role_title: parsed.role_title || 'Unknown',
  company: parsed.company || 'Unknown',
  job_url: input.job_url,
  eligible: true,
  role_fit,
  stage,
  founder_proximity,
  skills_tools,
  location,
  total,
  score,
  reason: parsed.reason || 'High alignment across profile factors',
  jd_in_german: step1.jd_in_german,
  scoring_failed: false,
  passes: score >= 4.0
};

